$script:Exp122Required=@('run-config.json','client-results.json','client-progress.jsonl','pool/pool-metrics.jsonl','pool/pool-metrics.jsonl.summary.json','pool/collector-coverage.json','application/container-stop.json','application/docker-logs.stdout.log','application/docker-logs.stderr.log','application/docker-logs-capture.json','application/application.log','database/database-metrics.jsonl','container/container-stats.jsonl','mock/load-stop-mock-metrics.json','drain/mock-drain-summary.json','verification-summary.json','provenance/runtime-provenance.json','provenance/execution-timeline.json','execution-summary.json')
function Write-Exp122Json($Value,$Path){New-Item -ItemType Directory -Force (Split-Path $Path)|Out-Null;$Value|ConvertTo-Json -Depth 12|Set-Content $Path -Encoding UTF8}
function Test-Exp122Json([string]$Path){try{$null=Get-Content $Path -Raw|ConvertFrom-Json;$true}catch{$false}}
function Get-Exp122Timestamp([object]$Object,[string]$Key,[bool]$Required=$true){$v=[string]$Object.$Key;if([string]::IsNullOrWhiteSpace($v)){if($Required){throw "Timestamp missing: $Key"};return $null};$d=[DateTimeOffset]::MinValue;if(-not[DateTimeOffset]::TryParse($v,[ref]$d)){throw "Timestamp invalid: $Key"};$d}
function Assert-Exp122Timeline([object]$Timeline){$keys=@('collectorProcessStartedAt','collectorFirstValidSampleAt','coreInvocationStartedAt','coreInvocationCompletedAt','collectorProcessCompletedAt','applicationStopStartedAt','applicationStopCompletedAt','applicationLogCaptureStartedAt','applicationLogCaptureCompletedAt');$t=@{};foreach($k in $keys){$t[$k]=Get-Exp122Timestamp $Timeline $k $true};for($i=1;$i-lt$keys.Count;$i++){if($t[$keys[$i]]-lt$t[$keys[$i-1]]){throw "Timeline order invalid: $($keys[$i-1]) -> $($keys[$i])"}}}
function Assert-Exp122BaseArtifacts([string]$Root){$zero=@('application/docker-logs.stdout.log','application/docker-logs.stderr.log');foreach($r in $script:Exp122Required){$p=Join-Path $Root $r;if(-not(Test-Path $p)){throw "Required artifact missing: $r"};if($zero-notcontains$r-and(Get-Item $p).Length-le0){throw "Required artifact empty: $r"}};foreach($r in @('run-config.json','client-results.json','pool/pool-metrics.jsonl.summary.json','pool/collector-coverage.json','application/container-stop.json','application/docker-logs-capture.json','mock/load-stop-mock-metrics.json','drain/mock-drain-summary.json','verification-summary.json','provenance/runtime-provenance.json','provenance/execution-timeline.json','execution-summary.json')){if(-not(Test-Exp122Json(Join-Path $Root $r))){throw "Invalid JSON: $r"}};$lines=@(Get-Content(Join-Path $Root 'pool/pool-metrics.jsonl')|Where-Object{$_.Trim()});if($lines.Count-le1){throw 'Pool JSONL has fewer than two samples'};foreach($line in $lines){try{$null=$line|ConvertFrom-Json}catch{throw 'Pool JSONL invalid'}};$ps=Get-Content(Join-Path $Root 'pool/pool-metrics.jsonl.summary.json')-Raw|ConvertFrom-Json;if($ps.failures-ne0){throw 'Pool collector failures'};. (Join-Path $PSScriptRoot 'experiment-1-22-collector-coverage.ps1');Assert-Exp122CollectorCoverage(Join-Path $Root 'pool/collector-coverage.json');$stop=Get-Content(Join-Path $Root 'application/container-stop.json')-Raw|ConvertFrom-Json;if($stop.stopStatus-ne'APPLICATION_CONTAINER_STOPPED'-or$stop.exitCode-ne0-or$stop.containerStillExists-ne$true-or[string]$stop.stateAfter-match'running'){throw 'Container stop validation failed'};$cap=Get-Content(Join-Path $Root 'application/docker-logs-capture.json')-Raw|ConvertFrom-Json;if($cap.captureMode-ne'POST_STOP_SNAPSHOT'-or$cap.timedOut-ne$false-or[string]$cap.containerStateAtCapture-match'running'-or$cap.captureStatus-ne'APPLICATION_LOG_CAPTURE_PASSED'-or$cap.exitCode-ne0-or($cap.stdoutBytes+$cap.stderrBytes)-le0){throw 'Post-stop capture validation failed'};$rc=Get-Content(Join-Path $Root 'run-config.json')-Raw|ConvertFrom-Json;if($cap.runId-ne$rc.runId){throw 'Capture runId mismatch'};$appRoot=([IO.Path]::GetFullPath((Join-Path $Root 'application'))).TrimEnd('\')+'\';foreach($p in @($cap.stdoutPath,$cap.stderrPath,$cap.combinedPath)){if(-not(Test-Path $p)){throw "Capture path missing: $p"};if(-not([IO.Path]::GetFullPath($p).StartsWith($appRoot,[StringComparison]::OrdinalIgnoreCase))){throw "Capture path outside application: $p"}};if([int64]$cap.stdoutBytes-ne[IO.File]::ReadAllBytes($cap.stdoutPath).Length-or[int64]$cap.stderrBytes-ne[IO.File]::ReadAllBytes($cap.stderrPath).Length-or[int64]$cap.combinedBytes-ne[IO.File]::ReadAllBytes($cap.combinedPath).Length){throw 'Capture byte mismatch'};if((Get-Exp122Timestamp $cap 'completedAt')-lt(Get-Exp122Timestamp $cap 'startedAt')){throw 'Capture time order invalid'};Assert-Exp122Timeline(Get-Content(Join-Path $Root 'provenance/execution-timeline.json')-Raw|ConvertFrom-Json)}
function Assert-Exp122StructuralArtifacts([string]$Root){Assert-Exp122BaseArtifacts $Root;$s=Get-Content(Join-Path $Root 'execution-summary.json')-Raw|ConvertFrom-Json;if($s.executionStatus-ne'FINALIZING'-or$s.artifactValidation-ne'PENDING'){throw 'Structural summary invalid'}}
function Assert-Exp122CommittedArtifacts([string]$Root){Assert-Exp122BaseArtifacts $Root;$s=Get-Content(Join-Path $Root 'execution-summary.json')-Raw|ConvertFrom-Json;if($s.executionStatus-ne'COMPLETED'-or$s.artifactValidation-ne'PASSED'){throw 'Committed summary invalid'};$tl=Get-Content(Join-Path $Root 'provenance/execution-timeline.json')-Raw|ConvertFrom-Json;Assert-Exp122Timeline $tl;$a=Get-Exp122Timestamp $tl 'artifactValidationCompletedAt';$f=Get-Exp122Timestamp $tl 'finalizationCompletedAt';if($f-lt$a){throw 'Finalization timestamp order invalid'}}
function Copy-Exp122Artifacts([string]$Legacy,[string]$Staging,[string]$Destination){$map=@(@('run-config.json','run-config.json'),@('client-results.json','client-results.json'),@('client-progress.jsonl','client-progress.jsonl'),@('database-metrics.jsonl','database/database-metrics.jsonl'),@('container-stats.jsonl','container/container-stats.jsonl'),@('load-stop-mock-metrics.json','mock/load-stop-mock-metrics.json'),@('mock-drain-summary.json','drain/mock-drain-summary.json'),@('verification-summary.json','verification-summary.json'));foreach($m in $map){$s=Join-Path $Legacy $m[0];if(-not(Test-Path $s)){throw "Legacy artifact missing: $s"};$d=Join-Path $Destination $m[1];New-Item -ItemType Directory -Force (Split-Path $d)|Out-Null;Copy-Item $s $d};foreach($n in @('pool-metrics.jsonl','pool-metrics.jsonl.summary.json')){$s=Join-Path $Staging $n;if(-not(Test-Path $s)){throw "Collector artifact missing: $s"};$d=Join-Path $Destination "pool/$n";New-Item -ItemType Directory -Force (Split-Path $d)|Out-Null;Copy-Item $s $d}}
function Set-Exp122Terminal([string]$Root,[ValidateSet('COMPLETED','EXECUTION_FAILED')][string]$State){foreach($m in @('RUNNING','COMPLETED','EXECUTION_FAILED')){Remove-Item(Join-Path $Root $m)-Force-ErrorAction SilentlyContinue};New-Item -ItemType File (Join-Path $Root $State)|Out-Null}

